"""
!
@defgroup MessengerLib
@brief Класс для работы с аккаунтами
"""

import logging
import socket
import time
from datetime import datetime
from typing import Optional, Union, Literal
from urllib.parse import urlparse, unquote

import allure
import requests
from opentelemetry.trace import get_current_span
from requests import Response, Session

from pyvkteamsclient.admin.exceptions import (
    RatelimitException,
    MissingParameterException,
    ServerException,
    AccessDeniedException,
    RequestException,
    HttpNotFoundException,
)
from pyvkteamsclient.tracer import tracer


class BaseAdminClient(object):
    """
    !
    Базовый класс создания и управления пользовательским инстансом
    """

    request_counter: int = 0
    logger = logging.getLogger(__name__)

    def __init__(
        self,
        session: Optional[Session] = None,
        api_url: str = "https://admin-vkorobov.v3.im-sandbox.devmail.ru",
        forced_ip: Optional[str] = None,
        env: Literal["SANDBOX", "ICQ", "SAAS", "PRE_SAAS", "VKTI", "PRE_VKTI", "TARM", "PRE_TARM"] = "SANDBOX",
    ):
        if session is None:
            session = Session()
        self.session = session
        self.session.verify = False

        self.env = env

        self.base_url = api_url
        self.forced_ip = forced_ip

    @tracer.start_as_current_span("base_admin.allure_attach")
    def allure_attach(self, response: requests.Response, return_str: bool = False):
        """
        Функция для логирования запроса-ответа в Allure отчете

        """
        date_str = str(datetime.now())
        headers_str = "\n".join([f"{k}: {v}" for k, v in response.request.headers.items()])

        text = f"{date_str}\n" f"{response.request.method} {response.request.url}\n" f"{headers_str}\n"

        if response.request.body:
            if isinstance(response.request.body, str):
                text += "\n" f"{unquote(response.request.body)}"

            elif isinstance(response.request.body, (bytes, bytearray)) and len(response.request.body) < 1000:
                try:
                    text += "\n" f"{unquote(response.request.body.decode())}"
                except UnicodeDecodeError:
                    text += "\n" f"Bytes {len(response.request.body)}"

            else:
                text += "\n" f"{type(response.request.body)}"

        text = text.strip()

        headers_str = "\n".join([f"{k}: {v}" for k, v in response.headers.items()])

        text += f"\n\n{response.status_code} {response.reason}\n" f"IP: {self.forced_ip}\n" f"{headers_str}\n"

        if response.text:
            if isinstance(response.text, str):
                text += "\n" f"{response.text}"
            else:
                text += "\n" f"{response.content.decode()}"

        self.logger.info(text)

        url_path = urlparse(response.url).path.replace("/", "_")

        allure.attach(
            text,
            name=f"{url_path}.log.txt",
            extension=allure.attachment_type.TEXT,
        )

        if return_str:
            return text

    @tracer.start_as_current_span("base_admin.restart_session")
    def restart_session(self): ...

    @tracer.start_as_current_span("base_admin.request")
    def request(
        self,
        method: Literal["GET", "POST", "PUT", "PATCH", "DELETE"],
        url: str,
        headers: Optional[dict[str, str]] = None,
        params: Optional[dict] = None,
        json: Optional[dict] = None,
        data: Optional[dict] = None,
        files=None,
        ignore_check: bool = False,
    ) -> dict:
        """
        Прокси-метод для всех запросов
        """
        self.request_counter += 1

        request = self.session.prepare_request(
            requests.Request(
                method=method,
                url=url,
                headers=headers,
                params=params,
                json=json,
                data=data,
                files=files,
            ),
        )

        if self.forced_ip is None:
            self.forced_ip = socket.gethostbyname(urlparse(request.url).netloc)

        error = None

        for i in range(3):
            try:
                response = self.session.send(request=request)
                response.encoding = "utf-8"
                self.allure_attach(response)
                if not ignore_check:
                    return self.check_response(response=response)
                else:
                    return response.json()
            except (
                RatelimitException,
                RequestException,
                MissingParameterException,
                ServerException,
                AccessDeniedException,
            ) as exc:
                error = exc
                self.logger.error(error)
                time.sleep(i)
                self.restart_session()

        else:
            raise error

    @tracer.start_as_current_span("base_admin.check_response")
    def check_response(self, response: Response) -> Union[dict, Exception]:
        """
        Проверка кода ответа API
        """
        if response.status_code == 429:
            raise RatelimitException(f"{response.request.path_url}")

        try:
            response_json = response.json()

            response_status_code = int(response_json.get("status", {}).get("code") or response.status_code)
            response_status_text = str(
                response_json.get("reason") or response_json.get("status", {}).get("reason") or response.reason,
            )
        except Exception as error:
            self.logger.error(error)
            response_json = response
            response_status_code = response.status_code
            response_status_text = "NoStatusText"

        span = get_current_span()
        if span.is_recording():
            span.set_attribute("response_status_code", response_status_code)
            span.set_attribute("response_status_text", response_status_text)

        if 200 <= response_status_code < 400 or 20000 <= response_status_code < 40000:
            return response_json

        elif response_status_code == 403:
            raise AccessDeniedException(
                env=self.env,
                path_url=response.request.path_url,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
                http_request_plain_text=self.allure_attach(response=response, return_str=True),
            )

        elif response_status_code == 404:
            raise HttpNotFoundException(
                env=self.env,
                path_url=response.request.path_url,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
                http_request_plain_text=self.allure_attach(response=response, return_str=True),
            )

        elif response_status_code in [429, 430]:
            raise RatelimitException(
                env=self.env,
                path_url=response.request.path_url,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
                http_request_plain_text=self.allure_attach(response=response, return_str=True),
            )

        elif response_status_code in (460, 462):
            raise MissingParameterException(
                env=self.env,
                path_url=response.request.path_url,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
                http_request_plain_text=self.allure_attach(response=response, return_str=True),
            )

        elif 400 <= response_status_code < 500 or 40000 <= response_status_code < 50000:
            raise RequestException(
                env=self.env,
                path_url=response.request.path_url,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
                http_request_plain_text=self.allure_attach(response=response, return_str=True),
            )

        else:
            raise ServerException(
                env=self.env,
                path_url=response.request.path_url,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
                http_request_plain_text=self.allure_attach(response=response, return_str=True),
            )

    @tracer.start_as_current_span("base_admin.get")
    @allure.step("[GET] Запрос к myteam-admin API {path}")
    def get(self, path: str, **kwargs) -> dict:
        """
        Оболочка для GET запросов к api ICQ/Myteam
        :param path: path для запроса
        :return: результат выполнения запроса (код и тело ответа)
        """
        return self.request(method="GET", url="/".join([self.base_url, path]), params=kwargs)

    @tracer.start_as_current_span("base_admin.post")
    @allure.step("[POST] Запрос к myteam-admin API {path}")
    def post(
        self,
        path: str,
        params: Optional[dict] = None,
        json: Optional[Union[dict, list]] = None,
        data: Optional[dict] = None,
        files=None,
    ) -> Union[dict, Response]:
        """
        Оболочка для POST запросов к api ICQ/Myteam
        :return: результат выполнения запроса (код и тело ответа)
        """
        return self.request(
            method="POST",
            url="/".join([self.base_url, path]),
            params=params,
            json=json,
            data=data,
            files=files,
        )

